(function(){
  'use strict';
  const M=window.FlowModel, KEY='airside-player-flow-study-v1', app=document.getElementById('app');
  const $=id=>document.getElementById(id), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money=n=>`$${Math.round(n).toLocaleString('en-AU')}`, signed=n=>`${n>=0?'+':'−'}${money(Math.abs(n))}`;
  let state=M.create(),ui={page:'title',tab:'goals',selected:'VH-PAX',stack:[],draft:null,filter:'All',base:'All',sort:'registration',modal:null,message:null,inbox:false,camera:'Follow',loadError:false,setup:{step:0,name:'Soak Air',code:'SA',colour:'#2c6080',coach:true},scenario:'starter'}, saved=null, toastTimer, lastTrigger=null, modalReturn=null;
  try{saved=JSON.parse(localStorage.getItem(KEY)||'null');}catch(_){ui.loadError=true;}
  const q=new URLSearchParams(location.search);if(['starter','growing','recovery'].includes(q.get('scenario'))){state=M.create(q.get('scenario'));ui.scenario=q.get('scenario');ui.page='airport';}
  const selected=()=>M.aircraft(state), button=(text,action,arg='',cls='',disabled='')=>`<button type="button" class="${cls}" data-action="${action}" data-arg="${esc(arg)}" ${disabled?'disabled':''}>${esc(text)}</button>`;
  const badge=(text,tone='')=>`<span class="badge ${tone}">${esc(text)}</span>`;
  const gated=(text,action,arg,reason,remedy='')=>`${button(text,action,arg,'',reason)}${reason?`<span class="reason">${esc(reason)}</span>${remedy}`:''}`;
  function pageTitle(title,description,body){return `<section class="workspace"><div class="workspace-head"><div><div class="eyebrow">${esc(state.name)} / ${ui.base==='All'?'All bases':esc(ui.base)}</div><h1>${esc(title)}</h1><p>${esc(description)}</p></div>${button('Back to airport','nav','airport','plain')}</div>${body}</section>`;}
  function tabs(items,current){return `<div class="tabs" role="group" aria-label="View choices">${items.map(([id,name])=>button(name,'tab',id,current===id?'active':'')).join('')}</div>`;}
  function empty(title,text,action=''){return `<div class="empty"><h3>${esc(title)}</h3><p style="margin-top:10px">${esc(text)}</p>${action?`<div class="actions" style="justify-content:center">${action}</div>`:''}</div>`;}
  const stamp=()=>`<div class="notice">Interactive design study. Airline values and transitions are sample data; the airport backdrop is a static game capture.</div>`;
  function go(page,opts={}){if(ui.page!==page||opts.force)ui.stack.push({page:ui.page,tab:ui.tab,selected:state.selected,draft:M.copy(ui.draft),base:ui.base,filter:ui.filter,camera:ui.camera,observed:ui.observed?M.copy(ui.observed):null});ui.page=page;if(opts.tab)ui.tab=opts.tab;if(opts.selected)state.selected=opts.selected;ui.inbox=false;render();}
  function back(){const last=ui.stack.pop();if(last){Object.assign(ui,last);state.selected=last.selected&&M.aircraft(state,last.selected)?last.selected:state.selected;}else ui.page='airport';ui.modal=null;render();}
  function showMessage(text,error=false){ui.message={text,error};render();clearTimeout(toastTimer);toastTimer=setTimeout(()=>{ui.message=null;render();},12000);$('announcement').textContent=text;}
  function perform(kind,args={},after){const result=M.action(state,kind,args);ui.modal=null;if(result.ok&&after)after();showMessage(result.ok?result.message:result.reason,!result.ok);return result;}
  function openPlanner(id=state.selected,code=null){state.selected=id;const a=M.aircraft(state,id);const r=M.ROUTES.find(x=>x.code===code)||M.ROUTES.find(x=>!M.routeReason(state,a,x));ui.draft={id,route:r?.code||'KGC',departure:state.time+15};go('planner');}
  function saveStudy(){try{localStorage.setItem(KEY,JSON.stringify(state));saved=M.copy(state);return true;}catch(_){ui.message={text:'The study could not be saved in this browser. Your current session is still available; download a study backup or keep this tab open.',error:true};return false;}}
  function confirm(title,body,kind,args,finalLabel){ui.modal={title,body,kind,args,finalLabel};render();}
  function header(){return `<header class="header"><div class="brand">AIRSIDE<span class="airline-name">/ ${esc(state.name)}</span></div><nav class="nav" aria-label="Main navigation">${[['airport','Airport'],['schedule','Schedule'],['network','Network'],['fleet','Fleet'],['career','Career']].map(([id,name])=>button(name,'nav',id,(ui.page===id||ui.page==='planner'&&id==='schedule'||ui.page==='profile'&&id==='fleet'?'active':'')+' nav-item')).join('')}</nav><div class="header-right"><span class="summary number">${money(state.funds)} · ${state.reliability}% · ${M.tierName(state.tier)}</span><span>Adelaide ${M.clock(state.time)}</span>${button('Menu','menu','','plain')}</div></header><div class="study-bar"><span>PLAYER FLOW STUDY · sample airline / static gameplay backdrop</span><div class="row gap8">${button('Study controls','study','','small')}${button('Next sample event','advance',state.selected,'small',!selected()?.booking&&!selected()?.job&&!selected()?.repeat)}${button(`Attention ${attention().length}`,'inbox','','small')}</div></div>`;}
  function attention(){const items=[];for(const a of state.fleet){if(a.wear>=85&&!a.job)items.push({id:a.id,text:'Check required before dispatch',kind:'decision'});if(a.repeat?.paused)items.push({id:a.id,text:`Repeat paused: ${a.repeat.reason||'Paused by you'}`,kind:'decision'});if(a.job&&state.issue==='return'&&a.job.stage===7)items.push({id:a.id,text:'Waiting for a compatible return stand',kind:'automatic'});}if(state.issue==='ground')items.push({id:state.fleet[0]?.id,text:'Taxi clearance held by EM204',kind:'automatic'});return items.filter(x=>x.id);}
  function tray(){const a=selected();if(!a)return `<footer class="flight-tray"><div class="row between"><span>No aircraft owned. Compare offers at an open base.</span>${button('View aircraft offers','market','','primary')}</div></footer>`;const b=a.booking;const route=b?(b.ferry?'→ Adelaide':`${a.base} → ${b.route}`):a.base;return `<footer class="flight-tray"><div class="eyebrow">${a.job?'SELECTED MAINTENANCE JOB':b?'YOUR SELECTED FLIGHT':'YOUR SELECTED AIRCRAFT'}</div><div class="tray-row"><div class="tray-field"><strong>${esc(a.id)}</strong></div><div class="tray-field">${esc(M.TYPES[a.type].name)}</div><div class="tray-field">${esc(route)}</div><div class="tray-field">${badge(M.availability(a),a.job?'warn':'')}</div>${b&&!b.ferry?`<span class="tray-field number">Departure ${M.clock(b.departure)}</span>`:''}<div class="tray-right">${button(a.job?'View check':b?'View rotation':'Plan rotation',a.job||b?'profile':'plan',a.id,'primary')}${button('All flights','nav','schedule')}</div></div></footer>`;}
  function airport(){const a=selected();return `<div class="airport-panel"><div class="eyebrow">Your next decision</div><h2 style="margin-top:8px">${state.coach?'Your airline starts here':attention().length?'Check what needs attention':'Room to plan your next service'}</h2><p>${state.coach?'Select your Saab, choose a route, then review and schedule the rotation. Ground servicing and tower clearances run automatically.':`${state.fleet.length} aircraft across ${state.bases.length} base${state.bases.length>1?'s':''}. You manage the airline; the airport keeps operating.`}</p><div class="actions">${button(a?.booking||a?.job?'View current work':'Plan a rotation',a?.booking||a?.job?'profile':'plan',a?.id||'', 'primary',!a)}${button('Choose growth goal','career-tab','goals','link')}</div></div>${a&&a.base==='ADL'?`<button class="airport-pin" data-action="profile" data-arg="${esc(a.id)}">✈ ${esc(a.id)} · ${esc(M.availability(a))}</button>`:''}<div class="airport-tools"><div class="eyebrow">Explore the airport</div><div class="row gap8">${button('Aircraft views','watch',a?.id||'','small',!a)}${button('Other traffic','traffic','','small')}${button('Radar / routes','nav','network','small')}</div><p class="muted" style="font-size:11px;margin-top:12px">Unlabelled gameplay capture, 30 September. Aircraft marker is illustrative.</p></div>`;}
  function flightRows(){let list=state.fleet.filter(a=>(ui.base==='All'||a.base===ui.base)&&(ui.filter==='All'||ui.filter==='Available'&&!a.booking&&!a.job||ui.filter==='Active'&&(a.booking||a.job)||ui.filter==='Attention'&&attention().some(x=>x.id===a.id)));if(ui.sort==='activity')list.sort((a,b)=>M.availability(a).localeCompare(M.availability(b)));else list.sort((a,b)=>a.id.localeCompare(b.id));return list.map(a=>`<tr class="${a.id===state.selected?'selected':''}"><td><strong>${esc(a.id)}</strong><small>${esc(M.TYPES[a.type].name)} · ${esc(a.role)}</small></td><td>${esc(a.base)}<small>${esc(a.stand)}</small></td><td>${a.booking?`${esc(a.base)} → ${esc(a.booking.route)}`:'—'}</td><td>${badge(M.availability(a),a.wear>=85?'warn':'')}<small>${a.repeat?`Repeat ${a.repeat.paused?'paused':'enabled'}`:a.wear>=85?'Check needed':''}</small></td><td class="number">${a.booking?M.clock(a.booking.departure):a.job?'After check / return':'Now'}</td><td>${button('Details','profile',a.id,'small')}</td></tr>`).join('');}
  function filters(){return `<div class="row between" style="margin-bottom:18px"><div class="row gap8"><label class="muted">Base <select id="base-filter" aria-label="Base filter"><option>All</option>${state.bases.map(b=>`<option ${ui.base===b.code?'selected':''}>${b.code}</option>`).join('')}</select></label><label class="muted">Show <select id="fleet-filter" aria-label="Activity filter">${['All','Available','Active','Attention'].map(x=>`<option ${ui.filter===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="muted">Sort <select id="fleet-sort" aria-label="Fleet sort"><option value="registration" ${ui.sort==='registration'?'selected':''}>Registration</option><option value="activity" ${ui.sort==='activity'?'selected':''}>Activity</option></select></label></div>${button('Add aircraft','market',ui.base==='All'?'ADL':ui.base,'primary')}</div>`;}
  function roster(){return `<div class="table-wrap"><table><thead><tr><th>Aircraft</th><th>Base / stand</th><th>Assignment</th><th>Activity</th><th>Availability</th><th></th></tr></thead><tbody>${flightRows()}</tbody></table></div>${flightRows()?'':empty('No aircraft match this view','Try All aircraft or another base.')}`;}
  function schedule(){return pageTitle('Schedule','Every committed service, available aircraft and repeat plan. Choose a flight to manage its next step.',`${filters()}${roster()}<div class="rule row between"><p class="muted">Bookings continue while you browse. Closing this page does not cancel a flight.</p>${button('Review recent results','career-tab','history','link')}</div>`);}
  function fleet(){return pageTitle('Fleet','One fleet across every base. Inspect an aircraft, manage its availability, or compare your next purchase.',`${tabs([['roster','Aircraft'],['bases','Bases & capacity']],ui.tab)}${ui.tab==='bases'?bases():`${filters()}${roster()}`}`);}
  function bases(){return `<div class="cards">${state.bases.map(b=>`<article class="card"><div class="eyebrow">${esc(b.code)}</div><h2>${esc(b.name)}</h2><p>${state.fleet.filter(a=>a.base===b.code).length} / ${b.capacity} aircraft capacity<br>${b.code==='ADL'?['Regional starter','Expanded regional','Domestic operating base'][state.level]:'Remote timed services; no on-field camera'}</p><div class="actions">${button('Compare aircraft','market',b.code,'primary')}${b.code==='ADL'?gated('Upgrade base','upgrade','',state.level>=2?'Sample capability is already fully upgraded.':''):''}</div></article>`).join('')}<article class="card"><div class="eyebrow">Grow the network</div><h2>Open an outstation</h2><p>Domestic capability and an opening commitment. Review before paying.</p><div class="actions">${button('Review base openings','base-review','','',state.tier<2)}</div>${state.tier<2?'<span class="reason">Domestic capability required.</span>'+button('View requirements','career-tab','goals','link'):''}</article></div>`;}
  function profile(){const a=selected();if(!a)return pageTitle('Aircraft unavailable','This aircraft may have been sold. Your roster has been refreshed.',button('Open fleet','nav','fleet','primary'));const t=M.TYPES[a.type],b=a.booking;return pageTitle(a.id,`${t.name} · ${a.role} · ${a.base}`,`<div class="split"><div>${badge(M.availability(a),a.job?'warn':'')}<dl class="details rule"><div><dt>Location</dt><dd>${esc(a.stand)} · ${esc(a.base)}</dd></div><div><dt>Readiness</dt><dd>${a.job?'Unavailable until check and return finish':`${100-a.wear}% condition${a.wear>=85?' · check required':''}`}</dd></div><div><dt>Completed services</dt><dd>${a.flights}</dd></div><div><dt>Resale value</dt><dd>${money(t.resale)}</dd></div></dl>${a.job?jobDetails(a):b?bookingDetails(a):`<div class="notice">This aircraft is available. Choose work that fits its route range, role and base.</div><div class="actions">${button('Plan rotation','plan',a.id,'primary')}${button('Find routes','route-aircraft',a.id)}</div>`}<section class="rule"><h3>Aircraft logbook</h3>${state.history.filter(x=>x.aircraft===a.id).length?historyTable(state.history.filter(x=>x.aircraft===a.id)):empty('No sample settlements yet','Completed commercial flights appear here. Ferry moves do not count as services.')}</section></div><aside class="sidebar stack"><section><h3>Watch this aircraft</h3><div class="actions">${gated('Open views','watch',a.id,a.base!=='ADL'?'This outstation aircraft has no rendered camera. Use map/status or ferry it to Adelaide.':'',button('Locate on network','nav','network','link'))}</div></section><section class="rule"><h3>Readiness & role</h3><div class="actions">${gated('Request maintenance','check-review',a.id,M.checkReason(state,a))}${gated(`Refit to ${a.role==='Passenger'?'freighter':'passenger'}`,'refit-review',a.id,a.type!=='SF34'?'This sample conversion is offered for the Saab only.':a.booking||a.job?'Finish current work before refitting.':'')}${gated('Assign stand','stand-review',a.id,a.base!=='ADL'?'Stand assignment is local to Adelaide.':a.booking||a.job?'Assign while the aircraft is available.':'')}</div></section><section class="rule"><h3>Repeat schedule</h3>${repeatDetails(a)}</section><section class="rule"><h3>Ownership</h3><div class="actions">${a.base!=='ADL'?gated('Ferry to Adelaide','ferry-review',a.id,M.ferryReason(state,a)):''}${gated('Sell aircraft','sell-review',a.id,M.sellReason(a))}</div></section></aside></div>`);}
  function bookingDetails(a){const b=a.booking;if(b.ferry)return `<div class="notice rule">Ferry to Adelaide · ${money(b.cost)} dispatch paid. Registration, wear and history are retained. No revenue or commercial flight credit.</div>`;const phases=['Fuelling','Boarding','Ready to depart','Taxiing','En route','Returning','Unloading'];return `<section class="rule"><h3>${a.base} → ${esc(b.route)}</h3><p class="muted" style="margin-top:10px">Departure ${M.clock(b.departure)} · ${money(b.cost)} dispatch paid · estimated return ${money(b.expected)}</p>${state.issue==='ground'?`<div class="notice warn rule">Waiting for EM204 at the taxi holding point. Tower will handle clearance. ${button('Inspect blocking aircraft','blocker','','link')}</div>`:''}<ol class="timeline">${phases.map((p,i)=>`<li class="${i<b.stage?'done':i===b.stage?'current':''}">${p}</li>`).join('')}</ol><div class="actions">${button('Watch flight','watch',a.id,'primary')}${gated('Cancel booking','cancel-review',a.id,M.cancelReason(a))}</div><p class="muted" style="font-size:12px;margin-top:12px">To change this commitment, review cancellation first, then create a new booking. Closing details leaves it intact.</p></section>`;}
  function jobDetails(a){const j=a.job;return `<section class="rule"><h3>${j.timed?'Outsourced timed check':M.PHASES[j.stage]}</h3><p class="muted" style="margin-top:10px">${j.timed?'This type/base uses a timed check; no local shed journey is shown.':'No passengers, baggage or commercial settlement. Repair work and travel are separate.'}</p>${!j.timed?`<ol class="timeline">${M.PHASES.map((p,i)=>`<li class="${i<j.stage?'done':i===j.stage?'current':''}">${p}</li>`).join('')}</ol>`:''}${j.repaired?'<div class="notice">Wear reset after repair. Dispatch remains blocked until the aircraft parks.</div>':''}${state.issue==='return'&&j.stage===7?'<div class="notice warn rule">No compatible return stand is free. Aircraft waits safely; no second charge.</div>':''}<div class="actions">${gated('Follow aircraft','watch',a.id,a.base!=='ADL'?'No camera at remote base.':'')}</div></section>`;}
  function repeatDetails(a){return a.repeat?`<p style="margin-top:12px">${esc(a.repeat.route)} · every ${a.repeat.interval} h · ${badge(a.repeat.paused?'Paused':'Enabled',a.repeat.paused?'warn':'good')}</p>${a.repeat.reason?`<span class="reason">${esc(a.repeat.reason)}</span>`:''}<p class="muted" style="font-size:12px;margin-top:10px">Only future bookings are affected. Existing commitment remains.</p><div class="actions">${button(a.repeat.paused?'Resume repeat':'Pause repeat','repeat-pause',a.id)}${button('Remove plan','repeat-remove-review',a.id,'plain')}</div>`:`<p class="muted" style="margin-top:12px">Earned after 12 manually planned services. No new bookings while the game is closed.</p><div class="actions">${gated('Create repeat plan','repeat-review',a.id,state.manual<12?`${state.manual} / 12 manual services. Keep planning rotations.`:'')}</div>`;}
  function planner(){const d=ui.draft||{id:state.selected,route:'KGC',departure:state.time+15},a=M.aircraft(state,d.id),r=M.route(d.route),f=a&&r?M.forecast(a,r):null,reason=M.scheduleReason(state,a,r,d.departure);return pageTitle('Plan a rotation','Choose an aircraft, destination and departure. Review the commitment before dispatch.',`<div class="split"><section><div class="form"><label>Aircraft<select id="plan-aircraft">${state.fleet.map(x=>`<option value="${esc(x.id)}" ${d.id===x.id?'selected':''}>${esc(x.id)} · ${esc(M.TYPES[x.type].name)} · ${esc(x.base)} · ${esc(M.availability(x))}</option>`).join('')}</select></label><label>Destination<select id="plan-route">${M.ROUTES.map(x=>`<option value="${x.code}" ${d.route===x.code?'selected':''}>${x.from} → ${x.code} · ${x.name}${M.routeReason(state,a,x)?' — unavailable':''}</option>`).join('')}</select></label><label>Departure time<input id="plan-time" type="time" value="${M.clock(d.departure)}"><small>Sample clock ${M.clock(state.time)}. Allow at least 10 minutes for preparation.</small></label></div>${reason?`<div class="notice warn rule" id="plan-reason">${esc(reason)}</div>`:'<div class="notice rule">This sample aircraft is eligible. Review costs and confirm the booking.</div>'}<div class="actions">${button('Review rotation','plan-review','','primary',reason)}${button('Browse routes','nav','network')}${button('Back','back','','plain')}</div></section><aside class="sidebar"><h2>Commitment summary</h2>${f?`<dl class="details rule"><div><dt>Route</dt><dd>${r.from} → ${r.code}<br>${r.km.toLocaleString()} km</dd></div><div><dt>Expected occupancy</dt><dd>${a.role==='Passenger'?`${f.seats} / ${M.TYPES[a.type].seats} seats`:'Freight role · sample load'}</dd></div><div><dt>Dispatch cost</dt><dd>${money(f.cost)} paid when booked</dd></div><div><dt>Estimated service return</dt><dd>${money(f.revenue)} at completion</dd></div><div><dt>Estimated operating margin</dt><dd>${signed(f.margin)}</dd></div><div><dt>Available funds</dt><dd>${money(state.funds)}</dd></div></dl>`:''}<p class="muted rule">Forecast figures are illustrative. Contract pay is reported separately when an eligible service settles.</p>${state.contract?`<p class="rule">Active contract: ${esc(M.CONTRACTS.find(x=>x.id===state.contract.id).title)} · ${state.contract.progress} rotations completed</p>${button('View contract','career-tab','contracts','link')}`:button('Find a matching contract','career-tab','contracts','link')}</aside></div>`);}
  function map(){return `<div class="route-map" aria-label="Schematic network diagram, not a geographic map"><svg viewBox="0 0 600 260" role="img"><title>Schematic route connections from Adelaide and Melbourne</title><path d="M285 155 L165 200 M285 155 L135 125 M285 155 L340 65 M285 155 L430 210 M430 210 L520 100 M285 155 L60 40" fill="none" stroke="#94b3bd" stroke-width="2" stroke-dasharray="4 5"/>${[[285,155,'Adelaide'],[165,200,'Kingscote'],[135,125,'Port Lincoln'],[340,65,'Broken Hill'],[430,210,'Melbourne'],[520,100,'Sydney'],[60,40,'Singapore']].map(([x,y,n])=>`<circle cx="${x}" cy="${y}" r="5" fill="#316982"/><text x="${x+10}" y="${y+4}" class="map-label">${n}</text>`).join('')}<text x="20" y="247" class="map-label">SCHEMATIC · current routes and aircraft fit are the decision</text></svg></div>`;}
  function network(){const a=selected();return pageTitle('Network','Find useful work for your aircraft. Unavailable routes explain what you need to change.',`${map()}<div class="row between" style="margin-bottom:18px"><span>Route fit for <strong>${esc(a?.id||'no aircraft')}</strong> · ${esc(a?.base||'—')}</span>${button('Choose another aircraft','nav','fleet')}</div><div class="cards">${M.ROUTES.map(r=>{const reason=M.routeReason(state,a,r);return `<article class="card"><div class="eyebrow">${r.from} → ${r.code} · ${r.km.toLocaleString()} km</div><h2>${r.name}</h2><p>${r.seats} expected passengers · ${M.tierName(r.tier)} capability<br>${a?`${M.TYPES[a.type].seats} aircraft seats · ${M.TYPES[a.type].range.toLocaleString()} km sample range`:''}</p><div class="actions">${gated('Plan this route','route-plan',r.code,reason,reason?button('View requirements','career-tab','goals','link'):'')}${r.from==='ADL'?button('Matching contracts','career-tab','contracts','link'):''}</div></article>`;}).join('')}</div><div class="rule row">${button('Inspect remote aircraft','remote','','')}${button('Inspect simulated traffic','traffic','','')}${button('Live-feed marker','live-feed','','plain')}</div>`);}
  function market(){const base=ui.base==='All'?'ADL':ui.base;return pageTitle('Compare aircraft',`Purchase destination: ${base}. Capability, capacity and price must fit before you commit.`,`<div class="form" style="max-width:350px;margin-bottom:24px"><label>Deliver to base<select id="market-base">${state.bases.map(b=>`<option value="${b.code}" ${base===b.code?'selected':''}>${b.name} (${b.code})</option>`).join('')}</select></label></div><div class="cards">${Object.entries(M.TYPES).map(([id,t])=>{const reason=M.buyReason(state,id,base);return `<article class="card"><div class="eyebrow">${M.tierName(t.tier)} aircraft</div><h2>${t.name}</h2><p>${t.seats} seats · ${t.range.toLocaleString()} km range<br>Sample price ${money(t.price)}<br>Fits ${base==='ADL'?id==='A320'?'terminal gates':'regional stands':'remote base capacity'}</p><div class="actions">${gated('Review purchase','buy-review',id,reason,reason?.includes('capacity')||reason?.includes('capability')?button('Review base capacity','fleet-tab','bases','link'):button('View career requirements','career-tab','goals','link'))}</div></article>`;}).join('')}</div><p class="muted rule">Study purchases are ready at the selected sample base. The game’s real delivery path must be shown from its simulation state.</p>`);}
  function career(){return pageTitle('Career','Choose meaningful growth, deliver your commitments, and review what your services achieved.',`${tabs([['goals','Goals'],['contracts','Contracts'],['history','Results & finances'],['identity','Airline profile']],ui.tab)}${ui.tab==='contracts'?contracts():ui.tab==='history'?history():ui.tab==='identity'?identity():goals()}`);}
  function goals(){return `<div class="metric-grid"><div class="metric"><div class="eyebrow">Capability</div><strong>${M.tierName(state.tier)}</strong></div><div class="metric"><div class="eyebrow">Completed services</div><strong>${state.flights}</strong></div><div class="metric"><div class="eyebrow">Reliability</div><strong>${state.reliability}%</strong></div></div><div class="cards">${[['first','Prove a regional service','Deliver three sample rotations; the first sample capability milestone.',state.flights>=3?'Completed':`${Math.min(3,state.flights)} / 3`, 'contracts','View contracts'],['fleet','Grow the fleet','Choose the right aircraft and compatible capacity for useful routes.',`${state.fleet.length} owned aircraft`,'market','Compare aircraft'],['network','Build a network','Review base capability and keep regional services profitable.',`${state.bases.length} open bases`,'bases','Review bases']].map(([id,title,copy,progress,target,label])=>`<article class="card"><div class="eyebrow">${state.goal===id?'Pinned goal':'Choose a direction'}</div><h2>${title}</h2><p>${copy}</p><div class="rule">${esc(progress)}</div><div class="actions">${button(label,'goal-link',target,'primary')}${button(state.goal===id?'Pinned':'Pin goal','pin',id,'',state.goal===id)}</div></article>`).join('')}</div><p class="muted rule">This sample progression is deliberately shortened for review. It does not change the game’s career pacing or established-airline requirements.</p>`;}
  function contracts(){return `${state.contract?`<div class="notice row between"><div><strong>${esc(M.CONTRACTS.find(c=>c.id===state.contract.id).title)}</strong><p>${state.contract.progress} / ${M.CONTRACTS.find(c=>c.id===state.contract.id).goal} eligible rotations complete</p></div><div class="row">${button('Plan eligible flight','contract-plan',state.contract.id,'primary')}${button('Review abandonment','abandon-review','','plain')}</div></div>`:''}<div class="cards" style="margin-top:20px">${M.CONTRACTS.map(c=>{const reason=M.contractReason(state,c);return `<article class="card"><div class="eyebrow">ADL → ${c.route} · ${c.role}</div><h2>${c.title}</h2><p>${c.goal} rotations · ${money(c.perFlight)} extra per eligible flight<br>${money(c.bonus)} completion reward<br>${esc(c.deadline)}</p><div class="actions">${gated('Review contract','contract-review',c.id,reason,reason?.includes('aircraft')?button('Review aircraft roles','nav','fleet','link'):'')}</div></article>`;}).join('')}</div><section class="rule"><h3>Contract history</h3>${state.contractHistory.length?`<ul class="activity">${state.contractHistory.map(c=>`<li>${esc(c.title)} · completed ${c.progress} rotations</li>`).join('')}</ul>`:empty('No completed contracts yet','Accepted commitments and completed results remain reviewable here.')}</section>`;}
  function historyTable(list){return `<div class="table-wrap"><table><thead><tr><th>Aircraft / route</th><th>Dispatch</th><th>Return</th><th>Contract pay</th><th>Net</th></tr></thead><tbody>${list.map(x=>`<tr><td>${esc(x.aircraft)} → ${esc(x.route)}<small>${x.at}${x.away?' · away completion':''}</small></td><td>${money(x.cost)}</td><td>${money(x.revenue)}</td><td>${money(x.bonus)}</td><td><strong>${signed(x.net)}</strong></td></tr>`).join('')}</tbody></table></div>`;}
  function history(){return `<div class="metric-grid"><div class="metric"><div class="eyebrow">Available funds</div><strong>${money(state.funds)}</strong></div><div class="metric"><div class="eyebrow">Net sample settlements</div><strong>${signed(state.history.reduce((n,x)=>n+x.net,0))}</strong></div><div class="metric"><div class="eyebrow">Paid services</div><strong>${state.history.length}</strong></div></div>${state.history.length?historyTable(state.history):empty('Your results start with your first return','Plan and finish a sample rotation to review the settlement.',button('Plan rotation','plan',state.selected,'primary',!selected()))}<section class="rule"><h3>Activity history</h3><ul class="activity">${state.events.map(e=>`<li><time>${e.at}</time>${esc(e.text)}</li>`).join('')||'<li class="muted">No changes yet.</li>'}</ul></section>`;}
  function identity(){return `<div class="split"><form id="identity-form" class="form"><label>Airline name<input id="identity-name" maxlength="40" required value="${esc(state.name)}"></label><label>Livery colour<input id="identity-colour" type="color" value="${esc(state.colour)}"></label><div class="actions"><button class="primary" type="submit">Apply identity</button></div></form><aside class="sidebar"><div class="colour-preview" style="background:${esc(state.colour)}">${esc(state.name)} · ${esc(state.code)}</div><p class="muted rule">Name and livery changes stay in this browser study. The sample aircraft image is not repainted.</p><dl class="details rule"><div><dt>Flight code</dt><dd>${esc(state.code)}</dd></div><div><dt>Pinned goal</dt><dd>${esc(state.goal)}</dd></div></dl></aside></div>`;}
  function watching(){const a=ui.observed||selected(),outside=ui.camera==='Follow'||ui.camera==='Exterior';const src=outside?'../../testing/aircraft-identities-2026-10-06/native/SF34.jpg':ui.camera==='Cockpit'?'../../testing/cockpit-mode-2026-10-01/v2-native-forward.png':'../../testing/passenger-flight-views-2026-10-01/left-sheet.jpg';return pageTitle(`Watch ${a?.id||'aircraft'}`,`${ui.camera} · static reference view; identity/status below reflect the selected sample aircraft.`,`<div class="view-frame"><img src="${src}" alt="Existing native ${esc(ui.camera)} reference; not a live camera feed"></div><div class="row between rule"><div class="row">${['Follow','Exterior','Cockpit','Cabin'].map(v=>gated(v,'camera',v,v==='Cabin'&&a?.role==='Freighter'?'Freighter has no passenger seats.':'')).join('')}</div>${button('Overview','nav','airport')}${ui.observed?button('Traffic details','blocker','','primary'):button('Flight details','profile',a?.id||'','primary')}</div><div class="notice rule">${a?`${esc(a.id)} · ${ui.observed?'Emu Air · holding short':esc(M.availability(a))}`:''}. Cameras are spectator views, not pilot controls. Reference images demonstrate placement only; they may show a different aircraft or earlier build.</div>${attention().length?`<div class="notice warn rule">${attention().length} airline item${attention().length>1?'s':''} need attention. ${button('Review attention','inbox','','link')}</div>`:''}`);}
  function title(){const has=M.validSave(saved);return `<main class="title-screen"><section class="title-card"><div class="brand">AIRSIDE</div><div class="eyebrow" style="margin-top:8px">Airline dispatch / interactive flow study</div><h1>A small airline. Your decisions.</h1><p>Try the complete player journeys before committing to an interface. All actions use a separate sample airline in this browser.</p>${ui.loadError?'<div class="notice error rule">The study save could not be loaded. It has been preserved. Restore a valid study backup or start a new sample; your Unity save is untouched.</div>':''}<div class="actions">${button(has?`Continue ${saved.name}`:'Continue saved study','continue','','primary',!has&&!ui.loadError)}${button('Start a new airline','new','','')}${button('How to play this study','help','','plain')}</div><div class="rule"><div class="eyebrow">Or review a later-career scenario</div><div class="title-scenarios">${button('Growing airline','scenario','growing','small')}${button('Disruption recovery','scenario','recovery','small')}</div></div>${ui.loadError?`<div class="actions">${button('Download preserved study save','backup','','small')}${button('Restore study backup','restore','','small')}${button('Clear error preview','clear-error','','small')}</div>`:''}<p class="foot">Design prototype · no live simulation · no Unity save access<br>Scenery references retain the game's existing source credits.</p></section></main>`;}
  function setup(){const x=ui.setup,step=x.step;return `<main class="title-screen"><section class="title-card"><div class="eyebrow">New airline · step ${step+1} of 3</div><h1>${['Your airline identity','Choose a livery','Your first service'][step]}</h1><form id="setup-form" class="form rule">${step===0?`<label>Airline name<input id="setup-name" maxlength="40" value="${esc(x.name)}" required></label><label>Flight code<input id="setup-code" maxlength="3" value="${esc(x.code)}" pattern="[A-Za-z]{2,3}" required><small>Two or three letters, for example SA.</small></label>`:step===1?`<label>Livery colour<input id="setup-colour" type="color" value="${esc(x.colour)}"></label><div class="colour-preview" style="background:${esc(x.colour)}">${esc(x.name)} · ${esc(x.code)}</div>`:`<div class="panel"><h3>${esc(x.name)}</h3><p>${esc(x.code)} · Adelaide base · Saab 340B VH-PAX</p><p>${money(2253)} starting sample funds · Provisional</p></div><label class="check"><input id="setup-coach" type="checkbox" ${x.coach?'checked':''}>Guide my first rotation</label><p class="muted">You choose the route and departure. Ground services, taxi clearances and flying are automatic.</p>`}<div class="actions">${button('Back',step?'setup-back':'title','','plain')}<button type="submit" class="primary">${step===2?'Start airline':'Continue'}</button></div></form></section></main>`;}
  function returnReport(){const last=state.history[0];return `<main class="title-screen"><section class="title-card"><div class="eyebrow">Welcome back / saved sample airline</div><h1>${esc(state.name)}</h1><p>Previously committed work can finish while away. No repeat plan created additional flights.</p><div class="metric-grid rule"><div><div class="eyebrow">Funds</div><h2>${money(state.funds)}</h2></div><div><div class="eyebrow">Owned fleet</div><h2>${state.fleet.length}</h2></div><div><div class="eyebrow">Attention</div><h2>${attention().length}</h2></div></div>${last?.away?`<div class="notice">${esc(last.aircraft)} finished its committed service. Net ${signed(last.net)}.</div>`:'<p class="muted">Your saved commitments and selection have been restored.</p>'}<ul class="activity rule">${state.fleet.map(a=>`<li><strong>${esc(a.id)}</strong> · ${esc(a.base)} · ${esc(M.availability(a))}</li>`).join('')}</ul><div class="actions">${button('Continue to airport','nav','airport','primary')}${button('Review results','career-tab','history')}</div></section></main>`;}
  function modalHtml(){const m=ui.modal;if(!m)return '';return `<div class="overlay" id="modal-layer"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="row between"><h2 id="dialog-title">${esc(m.title)}</h2>${button('Close','modal-close','','plain small')}</div>${m.body}<div class="actions">${button(m.kind?'Back':'Close','modal-close','','plain')}${m.kind?button(m.finalLabel||'Confirm','confirm','','primary'):''}</div></section></div>`;}
  function menu(study=false){ui.modal={title:study?'Study controls':'Menu',body:study?`<p>Move through sample events to test the flow. These controls are for design review, not proposed game time controls.</p><div class="actions">${button('Next selected event','advance',state.selected,'primary')}${button('Release automatic ground hold','clear-issue','','')}${button('No return stand available','issue','return')}${button('Ground hold','issue','ground')}${button('Low funds ($100)','low-funds','','')}</div><section class="study-controls"><h3>Review another career stage</h3><div class="actions">${button('Starter airline','scenario','starter')}${button('Growing airline','scenario','growing')}${button('Disruption recovery','scenario','recovery')}</div><p>Changing the sample resets this unsaved study session. It never changes the saved Unity game.</p></section><section class="study-controls"><h3>Save and recovery review</h3><div class="actions">${button('Save study','save','','')}${button('Preview load failure','load-error','','')}${button('Download study backup','backup','','')}${button('Restore study backup','restore','','')}</div></section>`:`<p>The airport keeps running when the game menu is open. This study uses manual sample events.</p><div class="stack rule">${button('Continue','modal-close','','primary')}${button('Settings','settings','','')}${button('Help & controls','help','','')}${button('Review activity history','career-tab','history')}${button('Save study and return to title','quit','','')}${button('Study controls','study','','plain')}</div>`};render();}
  function settings(){ui.modal={title:'Settings',body:`<p>Study preferences: review readability at different scales and surface contrast.</p><div class="form rule"><label class="check"><input type="checkbox" id="setting-dark" ${state.settings.dark?'checked':''}>Dark surfaces</label><label class="check"><input type="checkbox" id="setting-large" ${state.settings.large?'checked':''}>Larger text and controls</label><label class="check"><input type="checkbox" id="setting-sound" ${state.settings.sound?'checked':''}>Interface sounds (preference only in this study)</label><label class="check"><input type="checkbox" id="setting-motion" ${state.settings.motion?'checked':''}>Reduce camera motion (preference only)</label></div><div class="actions">${button('Restore defaults','settings-reset','','')}</div>`};render();}
  function help(){ui.modal={title:'How to use this flow study',body:`<ol class="help-list rule"><li>Start a new airline, or choose Growing airline to review purchases and bases.</li><li>Plan a rotation from the aircraft, Schedule, route or contract. Review the cost before committing.</li><li>Use Next sample event to walk through automatic servicing, flight and return. The study does not animate the airport.</li><li>Use Disruption recovery to inspect a ground hold, check requirement and paused repeat.</li><li>Save study and return to title to review away completion; previously committed flights finish once, repeats do not generate new work.</li><li>Escape / Back closes the current surface without cancelling work. Tab moves focus between controls.</li></ol><p>Existing game controls: F follow, R overview, right-drag orbit, drag/WASD pan, scroll zoom. These are not simulated here.</p><p>Scenery screenshots are from Airside's existing documentation and retain its OpenStreetMap, Copernicus, Sentinel and other recorded credits. This study introduces no external imagery, fonts or libraries.</p>`};render();}
  function render(){const focus=document.activeElement?.id;const previousModal=document.querySelector('[role="dialog"]');document.body.className=[state.settings.dark?'dark':'',state.settings.large?'large':''].join(' ');let html;
    if(ui.page==='title')html=title();else if(ui.page==='setup')html=setup();else if(ui.page==='return')html=returnReport();else {const pages={airport,schedule,fleet,profile,planner,network,market,career,watch:watching};html=`${header()}<div class="world" aria-hidden="true"><div class="world-image"></div><div class="world-caption">Static game capture · 30 Sep 2026</div></div><main class="main">${ui.stack.length&&ui.page!=='airport'?button('← Back','back','','plain back'):''}${(pages[ui.page]||airport)()}</main>${tray()}`;if(ui.inbox)html+=`<aside class="inbox" aria-label="Attention"><div class="row between"><h2>Attention</h2>${button('Close','inbox','','small plain')}</div>${attention().length?`<ul class="activity">${attention().map(x=>`<li><small class="eyebrow">${x.kind==='automatic'?'Automatic wait':'Your decision'}</small><p>${esc(x.text)}</p>${button(x.id,'profile',x.id,'link')}</li>`).join('')}</ul>`:'<p class="muted rule">No unresolved airline decision in this sample. Plan useful work or explore the airport.</p>'}</aside>`;}
    app.innerHTML=`<div id="study-shell" ${ui.modal?'inert aria-hidden="true"':''}>${html}</div>`+modalHtml()+(ui.message?`<div class="toast ${ui.message.error?'error':''}" role="status"><span>${esc(ui.message.text)}</span>${button('Dismiss','dismiss','','small plain')}</div>`:'');bind();if(focus&&$(focus))$(focus).focus();if(ui.modal&&!previousModal){modalReturn=lastTrigger;document.querySelector('[role="dialog"] button')?.focus();}else if(!ui.modal&&previousModal){const target=modalReturn?document.querySelector(`[data-action="${CSS.escape(modalReturn.action)}"][data-arg="${CSS.escape(modalReturn.arg)}"]`):null;(target||document.querySelector('.nav .active'))?.focus();modalReturn=null;} }
  function bind(){
    for(const [id,handler] of Object.entries({'base-filter':e=>{ui.base=e.target.value;render();},'fleet-filter':e=>{ui.filter=e.target.value;render();},'fleet-sort':e=>{ui.sort=e.target.value;render();},'market-base':e=>{ui.base=e.target.value;render();},'plan-aircraft':e=>{ui.draft.id=e.target.value;state.selected=e.target.value;render();},'plan-route':e=>{ui.draft.route=e.target.value;render();},'plan-time':e=>{const [h,m]=e.target.value.split(':').map(Number);ui.draft.departure=h*60+m;render();}}))if($(id))$(id).onchange=handler;
    if($('setup-form'))$('setup-form').onsubmit=e=>{e.preventDefault();const x=ui.setup;if(x.step===0){x.name=$('setup-name').value.trim();x.code=$('setup-code').value.trim().toUpperCase();if(!x.name||!(/^[A-Z]{2,3}$/).test(x.code)){showMessage('Enter an airline name and two or three letter flight code.',true);return;}}if(x.step===1)x.colour=$('setup-colour').value;if(x.step===2){x.coach=$('setup-coach').checked;state=M.create('starter',x.name,x.code,x.colour,x.coach);ui.page='airport';ui.stack=[];render();return;}x.step++;render();};
    if($('identity-form'))$('identity-form').onsubmit=e=>{e.preventDefault();const name=$('identity-name').value.trim();if(!name)return showMessage('Airline name cannot be blank.',true);state.name=name;state.colour=$('identity-colour').value;M.event(state,'Airline name and livery preference updated.');showMessage('Airline identity updated.');};
    for(const name of ['dark','large','sound','motion'])if($(`setting-${name}`))$(`setting-${name}`).onchange=e=>{state.settings[name]=e.target.checked;settings();};
    if($('repeat-form'))$('repeat-form').onsubmit=e=>{e.preventDefault();perform('repeat',{id:state.selected,route:$('repeat-route').value,interval:Number($('repeat-interval').value)});};
    if($('stand-form'))$('stand-form').onsubmit=e=>{e.preventDefault();perform('stand',{id:state.selected,stand:$('stand-choice').value});};
  }
  function click(action,arg){const a=M.aircraft(state,arg)||selected();
    if(action==='nav'){ui.modal=null;if(arg==='fleet')ui.tab='roster';if(arg==='career')ui.tab='goals';return go(arg);}
    if(action==='back')return back();if(action==='tab'){ui.tab=arg;return render();}
    if(action==='career-tab'){ui.modal=null;return go('career',{tab:arg});}if(action==='fleet-tab')return go('fleet',{tab:arg});
    if(action==='profile'){ui.modal=null;return go('profile',{selected:arg});}if(action==='plan')return openPlanner(arg||state.selected);
    if(action==='route-plan')return openPlanner(state.selected,arg);if(action==='route-aircraft'){state.selected=arg;return go('network');}
    if(action==='market'){ui.base=arg||'ADL';return go('market');}
    if(action==='plan-review'){const d=ui.draft,r=M.route(d.route),p=M.aircraft(state,d.id),f=M.forecast(p,r);return confirm('Review rotation',`<p><strong>${esc(p.id)} · ${r.from} → ${r.code}</strong><br>Departure ${M.clock(d.departure)} · ${esc(p.role)}</p><dl class="details rule"><div><dt>Pay now</dt><dd>${money(f.cost)}</dd></div><div><dt>Funds after booking</dt><dd>${money(state.funds-f.cost)}</dd></div><div><dt>Expected return</dt><dd>${money(f.revenue)}</dd></div><div><dt>Estimated margin</dt><dd>${signed(f.margin)}</dd></div></dl><p>Closing this review does not book the flight. Final acceptance rechecks funds and availability.</p>`,'schedule',{id:d.id,route:d.route,departure:d.departure},'Schedule rotation');}
    if(action==='confirm'){const m=ui.modal;if(!m?.kind)return;if(m.kind==='new'){ui.modal=null;ui.page='setup';ui.setup={step:0,name:'Soak Air',code:'SA',colour:'#2c6080',coach:true};return render();}if(m.kind==='scenario'){ui.modal=null;state=M.create(m.args.scenario);ui.page='airport';ui.stack=[];ui.draft=null;ui.base='All';ui.filter='All';return render();}const outcome=perform(m.kind,m.args,()=>{if(m.kind==='schedule'){ui.page='profile';state.selected=m.args.id;}if(m.kind==='buy')ui.page='profile';if(m.kind==='sell')ui.page='fleet';if(m.kind==='accept'){ui.page='career';ui.tab='contracts';}});return outcome;}
    if(action==='modal-close'){ui.modal=null;return render();}if(action==='dismiss'){ui.message=null;return render();}
    if(action==='inbox'){ui.inbox=!ui.inbox;return render();}if(action==='menu')return menu();if(action==='study')return menu(true);if(action==='help')return help();if(action==='settings')return settings();if(action==='settings-reset'){state.settings={dark:false,large:false,sound:true,motion:false};return settings();}
    if(action==='advance'){const result=perform('advance',{id:arg||state.selected});if(result.ok&&!a?.booking&&!a?.job){ui.page='career';ui.tab='history';render();}return;}
    if(action==='check-review')return confirm('Review maintenance check',`<p><strong>${esc(a.id)} · ${esc(M.TYPES[a.type].name)}</strong></p><p>Pay ${money(M.TYPES[a.type].check)} once. ${a.base==='ADL'&&a.type!=='A320'?'Prepare → taxi to shed → repair → return to a compatible stand.':'Timed outsourced check at this base/type; no local shed animation.'}</p><p>Aircraft remains unavailable until the entire job is finished. Maintenance earns no commercial revenue. Repeat plan cannot dispatch during the check.</p>`,'check',{id:a.id},`Start check for ${a.id}`);
    if(action==='cancel-review')return confirm('Cancel this booking?',`<p><strong>${esc(a.id)} → ${esc(a.booking?.route)}</strong></p><p>Sample policy: dispatch cost remains paid and reliability drops by 1 point. Existing repeat plan remains separate. This is cancellation, not a free booking edit.</p>`,'cancel',{id:a.id},'Cancel booking');
    if(action==='buy-review'){const t=M.TYPES[arg],base=ui.base==='All'?'ADL':ui.base;return confirm('Review aircraft purchase',`<p><strong>${t.name} at ${base}</strong></p><p>${t.seats} seats · ${t.range.toLocaleString()} km sample range.<br>Price ${money(t.price)} · funds remaining ${money(state.funds-t.price)}.<br>Uses one of ${M.capacity(state,base)} base slots. Ready immediately in this sample fixture.</p>`,'buy',{type:arg,base},`Buy ${t.name}`);}
    if(action==='sell-review')return confirm(`Sell ${a.id}?`,`<p>${esc(M.TYPES[a.type].name)} · ${a.base}</p><p>Receive ${money(M.TYPES[a.type].resale)}. This removes the aircraft and its repeat plan. A committed flight or maintenance job prevents the sale.</p>`,'sell',{id:a.id},`Sell ${a.id}`);
    if(action==='ferry-review')return confirm('Ferry to Adelaide',`<p><strong>${esc(a.id)} · ${a.base} → ADL</strong></p><p>Dispatch ${money(900)}. Adelaide needs capability, a compatible stand and free capacity including inbound ferries.</p><p>Registration, wear and history are retained. This ferry pays no revenue and earns no commercial flight credit.</p>`,'ferry',{id:a.id},'Dispatch ferry');
    if(action==='refit-review')return confirm('Change aircraft role',`<p>${esc(a.id)}: ${esc(a.role)} → ${a.role==='Passenger'?'Freighter':'Passenger'}.</p><p>No fee in this study fixture. Route/contract eligibility changes; freighters do not offer passenger seat views. Existing work must finish first.</p>`,'refit',{id:a.id},'Apply role change');
    if(action==='contract-review'){const c=M.CONTRACTS.find(x=>x.id===arg);return confirm('Review contract',`<p><strong>${c.title}</strong> · ADL → ${c.route}</p><p>${c.goal} eligible ${c.role.toLowerCase()} rotations · ${money(c.perFlight)} extra per flight · ${money(c.bonus)} completion reward.</p><p>${c.deadline}. Accepting does not automatically schedule services. An eligible aircraft must then be selected and booked.</p>`,'accept',{contract:arg},'Accept contract');}
    if(action==='contract-plan'){const c=M.CONTRACTS.find(x=>x.id===arg),p=state.fleet.find(x=>x.role===c.role&&!M.routeReason(state,x,M.route(c.route)));return p?openPlanner(p.id,c.route):showMessage('No eligible owned aircraft remains. Review Fleet.',true);}
    if(action==='abandon-review')return confirm('Abandon active contract?',`<p>Stops this commitment and discards its unfinished progress. Sample policy reduces reliability by 2 points. Already settled flights are not charged again.</p>`,'abandon',{},'Abandon contract');
    if(action==='stand-review'){state.selected=a.id;const stands=a.type==='A320'?['G1','G2']:['R1','R2','R3','R4'];ui.modal={title:'Assign a compatible stand',body:`<p>Assignment changes only through acceptance. Other reservations stay protected.</p><form id="stand-form" class="form rule"><label>Stand<select id="stand-choice">${stands.map(x=>`<option ${a.stand===x?'selected':''}>${x}</option>`).join('')}</select></label><button type="submit" class="primary">Assign stand</button></form>`};return render();}
    if(action==='repeat-review'){state.selected=a.id;ui.modal={title:'Create a repeat plan',body:`<p>Future bookings are made only while open. Existing booked services are unchanged. A refusal pauses the plan with a reason.</p><form id="repeat-form" class="form rule"><label>Destination<select id="repeat-route">${M.ROUTES.filter(r=>!M.routeReason(state,a,r)).map(r=>`<option value="${r.code}">${r.name} (${r.code})</option>`).join('')}</select></label><label>Interval<select id="repeat-interval"><option value="2">2 hours</option><option value="4" selected>4 hours</option><option value="8">8 hours</option></select></label><button type="submit" class="primary">Enable repeat</button></form>`};return render();}
    if(action==='repeat-pause')return perform('repeat-pause',{id:a.id});if(action==='repeat-remove-review')return confirm('Remove repeat plan?',`<p>Stops future automatic bookings for ${esc(a.id)}. Its current committed flight, if any, stays booked.</p>`,'repeat-remove',{id:a.id},'Remove repeat plan');
    if(action==='upgrade')return confirm('Upgrade Adelaide base',`<p>Sample upgrade ${money(18000)}. Adds operating capability and two aircraft slots, up to the current six-aircraft Adelaide allocation. Aircraft purchase remains a separate cost.</p>`,'upgrade',{},'Upgrade Adelaide');
    if(action==='base-review'){ui.modal={title:'Open an outstation',body:`<p>Sample opening cost ${money(25000)}. Eight aircraft slots per base; three outstations maximum. Remote services have no rendered local airport camera.</p><div class="actions">${['MEL','SYD','BNE','PER'].map(b=>button(`Review ${b}`,'base-confirm',b,'',state.bases.some(x=>x.code===b))).join('')}</div>`};return render();}
    if(action==='base-confirm')return confirm(`Open ${arg} base?`,`<p>Pay ${money(25000)}. Funds after opening ${money(state.funds-25000)}. Aircraft acquisition and route planning are separate next decisions.</p>`,'base',{base:arg},`Open ${arg} base`);
    if(action==='pin'){state.goal=arg;M.event(state,`Goal ${arg} pinned.`);return showMessage('Goal pinned. Use its linked next action.');}
    if(action==='goal-link'){if(arg==='contracts')return go('career',{tab:'contracts'});if(arg==='bases')return go('fleet',{tab:'bases'});ui.base='ADL';return go('market');}
    if(action==='watch'){if(a?.base!=='ADL')return showMessage('No camera is available at this remote base. Use network status or the supported ferry.',true);ui.observed=null;ui.camera='Follow';return go('watch',{selected:a.id});}
    if(action==='camera'){if(arg==='Cabin'&&(ui.observed||selected())?.role==='Freighter')return showMessage('Freighter has no passenger seats.',true);ui.camera=arg;return render();}
    if(action==='blocker'){ui.modal={title:'EM204 · simulated traffic',body:`<p>Emu Air · waiting at the holding point. Tower handles clearance; you cannot command another airline.</p><p>Back returns to ${esc(state.selected)}. Use Study controls to preview release of the automatic hold.</p><div class="actions">${button('Watch simulated aircraft','traffic-watch','','primary')}</div>`};return render();}
    if(action==='traffic-watch'){ui.modal=null;ui.observed={id:'EM204',role:'Passenger',type:'SF34',base:'ADL'};ui.camera='Follow';return go('watch');}
    if(action==='traffic'){ui.modal={title:'Other operators',body:`<p>Simulated aircraft remain inspectable. You manage your own airline, not their clearances.</p><div class="actions">${button('Inspect EM204','blocker','','')}${button('Inspect live-feed marker','live-feed','','plain')}</div>`};return render();}
    if(action==='live-feed'){ui.modal={title:'Live-feed traffic decoration',body:'<p>Reference marker only. Not a simulated actor; no schedule, settlement, cockpit or follow commands are available.</p>'};return render();}
    if(action==='remote'){const p=state.fleet.find(x=>x.base!=='ADL');return p?go('profile',{selected:p.id}):showMessage('No outstation aircraft in this sample. Growing airline includes one.');}
    if(action==='new'){if(saved||state.events.length)return confirm('Start a new sample airline?',`<p>Current unsaved study progress is replaced. The saved browser study remains until you explicitly save again. This never replaces a Unity save.</p>`,'new',{},'Start new sample');ui.page='setup';ui.setup.step=0;return render();}
    if(action==='setup-back'){ui.setup.step=Math.max(0,ui.setup.step-1);return render();}if(action==='title'){ui.modal=null;ui.page='title';return render();}
    if(action==='scenario'){if(ui.page==='title'){state=M.create(arg);ui.page='airport';ui.stack=[];return render();}return confirm('Change review scenario?',`<p>Replaces the unsaved local sample with ${esc(arg)}. Saved study data remains until you save this scenario.</p>`,'scenario',{scenario:arg},'Load sample scenario');}
    if(action==='save'){ui.modal=null;if(saveStudy())showMessage('Browser study saved. Your Unity save is untouched.');else render();return;}
    if(action==='quit'){ui.modal=null;if(saveStudy()){ui.page='title';ui.stack=[];}return render();}
    if(action==='continue'){if(ui.loadError||!M.validSave(saved)){ui.loadError=true;ui.page='title';return render();}state=M.copy(saved);ui.stack=[];for(const p of state.fleet){if(p.booking)M.advance(state,p.id,true);if(p.job?.timed)M.action(state,'advance',{id:p.id});}ui.page='return';if(!saveStudy())return render();return render();}
    if(action==='load-error'){if(!saveStudy())return render();ui.modal=null;ui.loadError=true;ui.page='title';return render();}if(action==='clear-error'){ui.loadError=false;return render();}
    if(action==='backup'){let text;try{text=localStorage.getItem(KEY)||JSON.stringify(state);}catch(_){text=JSON.stringify(state);}const blob=new Blob([text],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='airside-study-backup.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
    if(action==='restore'){const input=document.createElement('input');input.type='file';input.accept='.json';input.onchange=async()=>{try{const x=JSON.parse(await input.files[0].text());if(!M.validSave(x))throw Error('Invalid study file');state=x;if(!saveStudy())return render();ui.loadError=false;ui.modal=null;ui.page='return';showMessage('Study backup restored.');}catch(_){showMessage('Not a valid study backup. Existing saved data was preserved.',true);}};input.click();return;}
    if(action==='issue'){state.issue=arg;ui.modal=null;return showMessage(arg==='ground'?'Automatic ground hold added to sample.':'Return-stand wait added to sample.');}if(action==='clear-issue'){state.issue=null;ui.modal=null;return showMessage('Automatic obstruction released in the sample.');}if(action==='low-funds'){state.funds=100;ui.modal=null;return showMessage('Low-funds sample is ready. Plan/check/purchase refusals will keep your choices.');}
  }
  document.addEventListener('click',e=>{const b=e.target.closest('button[data-action]');if(!b||b.disabled)return;lastTrigger={action:b.dataset.action,arg:b.dataset.arg};click(b.dataset.action,b.dataset.arg);});
  document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(ui.modal){ui.modal=null;render();}else if(ui.inbox){ui.inbox=false;render();}else if(ui.page!=='airport'&&ui.page!=='title')back();else menu();}if(e.key==='Tab'&&ui.modal){const els=[...document.querySelectorAll('[role="dialog"] button:not(:disabled), [role="dialog"] input, [role="dialog"] select')].filter(x=>x.offsetParent!==null);if(els.length){const first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}});
  window.FlowStudy={snapshot:()=>M.copy(state),ui:()=>M.copy({...ui,modal:ui.modal?{title:ui.modal.title}:null})};
  render();
})();
